const replyError=error=>local(({AI_NOT_CONFIGURED:'Character replies are temporarily unavailable. Please try again.',AI_TIMEOUT:'The model is taking too long. Please try again.',AI_RATE_LIMIT:'The model service is busy. Please try again shortly.',AI_INTERRUPTED:'The reply was interrupted. The text already shown is kept.'})[error?.code]||'The model service is unavailable. Please try again later.');
