  history.innerHTML=entries.length?entries.slice(0,12).map(item=>{const last=lastSessionText(h.read('ooc-session-v2-'+item.id,null));return `<li class="session-history-item"><a href="/play/${safe(item.id)}" ${item.id===id?'aria-current="page"':''}><img src="${safe(item.image?.startsWith('assets/')?'/'+item.image:item.image||'')}" alt=""><span><strong>${safe(sessionLanguage()==='zh'?item.title_zh||item.title:item.title)}</strong><small>${safe(last?.replace(/[*#>\n]/g,' ').slice(0,85)||local(kind==='character'?'Start chatting':'Start your story'))}</small></span></a></li>`;}).join(''):`<li class="session-history-empty">${local('Your recent sessions will appear here.')}</li>`;
