let remoteToken=0;
function remoteSession(id,h){
 const token=++remoteToken;
 mountInteraction('<div class="shell-empty"><h1>Loading story…</h1></div>',h);
 fetch('/api/titles?id='+encodeURIComponent(id)).then(async r=>({ok:r.ok,data:await r.json().catch(()=>({}))})).then(({ok,data})=>{
  if(token!==remoteToken||!location.pathname.startsWith('/play/'+id))return;
  if(!ok||!data.title){mountInteraction(`<div class="shell-empty"><h1>Story unavailable</h1><p>${(data.error||'This title is not available.').replace(/[<>&]/g,'')}</p><a href="/community">Browse Community</a></div>`,h);return;}
  session(id,h,{...data.title,status:'published',publishedId:id});
 }).catch(()=>{if(token===remoteToken)mountInteraction('<div class="shell-empty"><h1>Story unavailable</h1><p>Could not reach the server.</p><a href="/community">Browse Community</a></div>',h);});
 return true;
}
export function show(path,helpers){cleanup();cleanup=()=>{};if(path.startsWith('/onboarding'))return onboard(path,helpers);if(path.startsWith('/play/')||/^\/(story|character)\/[^/]+\/episode\//.test(path)){const id=path.split('/')[2];if(/^u-/.test(id)&&!helpers.read('ooc-custom',[]).some(d=>d&&d.status==='published'&&d.publishedId===id))return remoteSession(id,helpers);return session(id,helpers);}return false;}
